def affected(lst1, lst2) -> bool:
    # The edit changes which lst2 elements are counted: x % 2 == 0 counts evens,
    # while x // 2 == 0 counts only 0 and 1. The return value differs exactly when
    # the odd count of lst1 lies between the two counts (min < a <= max).
    try:
        a = sum(1 for x in lst1 if x % 2 == 1)
        e = sum(1 for x in lst2 if x % 2 == 0)
        m = sum(1 for x in lst2 if x // 2 == 0)
    except Exception:
        return False
    return min(e, m) < a <= max(e, m)
